/*
 * This sketch measures distance with the HC-SR04 ultrasonic sensor
 * and reports the result in centimeters and inches over Serial.
 */

const byte TRIG_PIN = 9;
const byte ECHO_PIN = 8;
const unsigned long ECHO_TIMEOUT_US = 30000UL;

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  digitalWrite(TRIG_PIN, LOW);

  Serial.begin(115200);
  Serial.println(F("HC-SR04 distance reader"));
}

void loop() {
  unsigned long duration;
  float distanceCm;

  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);

  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  duration = pulseIn(ECHO_PIN, HIGH, ECHO_TIMEOUT_US);

  if (duration == 0) {
    Serial.println(F("Measurement timeout"));
  } else {
    distanceCm = duration * 0.0343f / 2.0f;

    Serial.print(F("Distance: "));
    Serial.print(distanceCm, 1);
    Serial.print(F(" cm ("));
    Serial.print(distanceCm / 2.54f, 1);
    Serial.println(F(" in)"));
  }

  delay(200);
}
